using System;
using System.Linq;
using Game.Net;
using Game.Pathfind;
using MW.EditorTools.Modules.BulldozerRecovery;
using Unity.Entities;
using Unity.Mathematics;

internal static class AreaCompanionChecks {
    private static int checks;
    private static void Check(bool value,string label){if(!value)throw new Exception("FAILED area companion: "+label);checks++;}
    private static Entity Id(int i)=>new Entity{Index=i,Version=1};
    private static AreaCompanionNetwork Graph(int offset=0) {
        var owner=Id(offset+1);var start=Id(offset+2);var end=Id(offset+3);var edge=Id(offset+4);var lane=Id(offset+5);
        var curve=new Curve{m_Bezier=new Colossal.Mathematics.Bezier4x3{a=new float3(0),b=new float3(3,0,0),c=new float3(7,0,0),d=new float3(10,0,0)},m_Length=10};
        return new AreaCompanionNetwork{Owner=owner,RootNets=new[]{start,end,edge},RootLanes=new[]{new SubLane{m_SubLane=lane}},Items=new[]{
            new AreaCompanionNetwork.Item{Id=start,Owner=owner,HasNode=true,Node=new Node{m_Position=new float3(0),m_Rotation=quaternion.identity},Connections=new[]{edge}},
            new AreaCompanionNetwork.Item{Id=end,Owner=owner,HasNode=true,Node=new Node{m_Position=new float3(10,0,0),m_Rotation=quaternion.identity},Connections=new[]{edge}},
            new AreaCompanionNetwork.Item{Id=edge,Owner=owner,HasEdge=true,HasCurve=true,Curve=curve,Edge=new Game.Net.Edge{m_Start=start,m_End=end},HasSeed=true,Seed=new Game.Common.PseudoRandomSeed{m_Seed=27}},
            new AreaCompanionNetwork.Item{Id=lane,Owner=owner,HasLane=true,HasCurve=true,Curve=curve,Lane=new Lane{m_StartNode=new PathNode(start,(ushort)7),m_MiddleNode=new PathNode(edge,(ushort)8),m_EndNode=new PathNode(end,(ushort)9)}}}};
    }
    internal static int Run() {
        Func<AreaCompanionEffect> effect=()=>new AreaCompanionEffect{Original=Id(6),HasTransform=true,Position=new float3(1,2,3),Rotation=quaternion.identity,Scale=new float3(1),Intensity=2,Group=4,HasLocal=true,
            Local=new Game.Tools.LocalTransformCache{m_Position=new float3(1,2,3),m_Rotation=quaternion.identity,m_ParentMesh=7},HasElevation=true,Elevation=new Game.Objects.Elevation{m_Elevation=3}};
        var e=effect();var f=effect();f.Original=Id(106);
        Check(AreaCompanionEffect.Matches(new[]{e},new[]{f}),"effect parameters roundtrip");
        f.Intensity=3;Check(!AreaCompanionEffect.Matches(new[]{e},new[]{f}),"effect intensity change refused");
        f=effect();f.Scale.x=2;Check(!AreaCompanionEffect.Matches(new[]{e},new[]{f}),"effect scale change refused");
        f=effect();f.Group=5;Check(!AreaCompanionEffect.Matches(new[]{e},new[]{f}),"effect animation group change refused");
        f=effect();f.Local.m_ParentMesh=8;Check(!AreaCompanionEffect.Matches(new[]{e},new[]{f}),"effect parent mesh change refused");
        f=effect();f.Elevation.m_Elevation=4;Check(!AreaCompanionEffect.Matches(new[]{e},new[]{f}),"effect elevation change refused");
        f=effect();f.Position.x=4;Check(!AreaCompanionEffect.Matches(new[]{e},new[]{f}),"effect position change refused");
        f=effect();f.HasLocal=false;Check(!AreaCompanionEffect.Matches(new[]{e},new[]{f}),"effect cache schema change refused");
        f=effect();f.Intensity=float.NaN;Check(!AreaCompanionEffect.Matches(new[]{f},new[]{f}),"nonfinite effect image refused");
        Check(!AreaCompanionEffect.Matches(new[]{e,e},new[]{effect(),effect()}),"ambiguous duplicate effects refused");
        Check(!AreaCompanionEffect.Matches(new[]{e},Array.Empty<AreaCompanionEffect>()),"missing effect companion refused");
        f=effect();f.Container=(Game.Prefabs.PrefabBase)System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(typeof(Game.Prefabs.ObjectPrefab));
        Check(!AreaCompanionEffect.Matches(new[]{e},new[]{f}),"effect container reference change refused");
        e.Prefab=null;f=effect();f.Prefab=(Game.Prefabs.PrefabBase)System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(typeof(Game.Prefabs.ObjectPrefab));
        Check(!AreaCompanionEffect.Matches(new[]{e},new[]{f}),"effect prefab reference change refused");
        var liveCache=effect().Local;liveCache.m_PrefabSubIndex=77;var detached=AreaCompanionEffect.DetachedLocal(liveCache);
        Check(liveCache.m_PrefabSubIndex==77&&detached.m_PrefabSubIndex==0&&detached.m_ParentMesh==7,"only detached effect cache index normalized");
        Check(AreaCompanionNetwork.SourcesValid(new[]{Id(2)},new[]{Id(102)},_=>false),"gone source can be replaced with new entity");
        Check(AreaCompanionNetwork.SourcesValid(new[]{Id(2)},new[]{Id(2)},_=>true),"reused source remains in mapped graph");
        Check(!AreaCompanionNetwork.SourcesValid(new[]{Id(2)},new[]{Id(102)},_=>true),"surviving orphan outside rebuilt graph refused");
        var expected=Graph();var actual=Graph(100);
        Check(expected.TryMap(actual,true,out var map)&&map[Id(4)]==Id(104),"recreated IDs map by native geometry");
        Check(expected.Items[3].Lane.m_StartNode.GetOwnerIndex()==2&&actual.Items[3].Lane.m_StartNode.GetOwnerIndex()==102,"path normalization never mutates images");
        actual.Items= new[]{actual.Items[3],actual.Items[1],actual.Items[0],actual.Items[2]};
        Check(expected.TryMap(actual,true,out _),"native enumeration order is irrelevant");
        actual=Graph(100);actual.Items[2].Edge.m_End=Id(102);
        Check(!expected.TryMap(actual,true,out _),"wrong edge endpoint refused");
        actual=Graph(100);actual.Items[0].Connections=Array.Empty<Entity>();
        Check(!expected.TryMap(actual,true,out _),"lost node connection refused");
        actual=Graph(100);actual.Items[0].Connections=new[]{Id(104),Id(104)};
        Check(!actual.TryMap(actual,true,out _),"duplicate connection refused");
        actual=Graph(100);actual.Items[3].Lane.m_StartNode=new PathNode(Id(103),(ushort)7);
        Check(!expected.TryMap(actual,true,out _),"wrong lane path owner refused");
        actual=Graph(100);actual.Items[3].Lane.m_StartNode=new PathNode(Id(102),(ushort)3);
        Check(!expected.TryMap(actual,true,out _),"lane index change refused");
        actual=Graph(100);actual.Items[3].Lane.m_StartNode=new PathNode(Id(999),(ushort)7);
        Check(!actual.TryMap(actual,true,out _),"external lane connection refused");
        actual=Graph(100);actual.Items[2].Curve.m_Bezier.b.x=4;
        Check(!expected.TryMap(actual,true,out _),"network curve change refused");
        actual=Graph(100);actual.Items[2].Curve.m_Length=20;
        Check(!expected.TryMap(actual,true,out _),"curve length change refused");
        actual=Graph(100);actual.Items[2].HasLocal=true;actual.Items[2].Local=new Game.Tools.LocalCurveCache{m_Curve=actual.Items[2].Curve.m_Bezier};
        Check(!expected.TryMap(actual,true,out _),"local curve schema change refused");
        actual=Graph(100);actual.Items[2].HasContainer=true;actual.Items[2].Container=(Game.Prefabs.PrefabBase)System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(typeof(Game.Prefabs.ObjectPrefab));
        Check(!expected.TryMap(actual,true,out _),"container presence/reference change refused");
        actual=Graph(100);actual.Items[2].Prefab=(Game.Prefabs.PrefabBase)System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(typeof(Game.Prefabs.ObjectPrefab));
        Check(!expected.TryMap(actual,true,out _),"prefab identity change refused");
        actual=Graph(100);actual.Items[2].Seed.m_Seed=99;
        Check(!expected.TryMap(actual,true,out _)&&expected.TryMap(actual,false,out _),"seed-only change admits restoration preflight but fails final validation");
        actual=Graph(100);actual.Items[0].Owner=Id(999);
        Check(!actual.TryMap(actual,true,out _),"external ownership refused");
        actual=Graph(100);actual.RootNets=new[]{Id(102),Id(104)};
        Check(!expected.TryMap(actual,true,out _),"root network membership preserved");
        actual=Graph(100);actual.RootLanes[0].m_PathMethods=(PathMethod)1;
        Check(!expected.TryMap(actual,true,out _),"lane link path methods preserved");
        actual=Graph(100);actual.Items[1].Node=actual.Items[0].Node;
        Check(actual.TryMap(actual,true,out _),"surviving identities distinguish coincident nodes with complete topology proof");
        var coincident=Graph();coincident.Items[1].Node=coincident.Items[0].Node;
        Check(!coincident.TryMap(actual,true,out _),"recreated coincident nodes without surviving identities remain ambiguous");
        actual.Items[2].Edge.m_End=Id(999);
        Check(!actual.TryMap(actual,true,out _),"surviving identities cannot bypass external endpoints");
        actual=Graph();actual.Items[2].Curve.m_Length++;
        Check(!Graph().TryMap(actual,true,out _),"surviving identity cannot bypass changed typed data");
        actual=Graph(100);actual.Items[0].Node.m_Position.x=float.NaN;
        Check(!actual.TryMap(actual,true,out _),"nonfinite native geometry refused");
        actual=Graph(100);actual.Items[0].Node.m_Rotation=new quaternion(0,0,0,-1);
        Check(expected.TryMap(actual,true,out _),"equivalent quaternion sign accepted");
        var cached=Graph();var regenerated=Graph(100);
        cached.Items[2].HasLocal=regenerated.Items[2].HasLocal=true;
        cached.Items[2].Local=new Game.Tools.LocalCurveCache{m_Curve=cached.Items[2].Curve.m_Bezier};
        regenerated.Items[2].Local=cached.Items[2].Local;regenerated.Items[2].Local.m_Curve.a.x=float.NaN;
        Check(!cached.TryMap(regenerated,true,out _),"invalid regenerated cache fails ordinary final graph validation");
        Check(cached.TryMap(regenerated,false,out var cachedMap,false)&&cachedMap[Id(4)]==Id(104),"cache repair preflight retains complete live topology mapping");
        Check(AreaCompanionNetwork.CanRestoreLocal(cached.Items[2].Local,regenerated.Items[2].Local),"captured finite cache may repair invalid regenerated cache");
        Check(!AreaCompanionNetwork.CanRestoreLocal(regenerated.Items[2].Local,regenerated.Items[2].Local),"invalid captured cache cannot be used as repair source");
        regenerated.Items[2].Local=cached.Items[2].Local;regenerated.Items[2].Local.m_Curve.b.x=8;
        Check(!AreaCompanionNetwork.CanRestoreLocal(cached.Items[2].Local,regenerated.Items[2].Local),"differing finite local curve cannot be silently overwritten");
        regenerated.Items[2].Local=cached.Items[2].Local;
        Check(cached.TryMap(regenerated,true,out _),"repaired cache passes strict final validation");
        regenerated.Items[2].Curve.m_Bezier.b.x=99;
        Check(!cached.TryMap(regenerated,false,out _,false),"cache repair cannot bypass live curve differences");
        regenerated=Graph(100);
        Check(!cached.TryMap(regenerated,false,out _,false),"cache repair cannot bypass local component presence");
        Check(!expected.TryMap(null,true,out _),"missing companion image refused");
        var worldBefore=Graph();var worldAfter=Graph(100);
        worldBefore.Items[2].Curve.m_Bezier.b.y=worldAfter.Items[2].Curve.m_Bezier.b.y=511.9453f;
        worldAfter.Items[2].Curve.m_Bezier.b.y+=0.0002f;
        Check(!worldBefore.TryMap(worldAfter,true,out _),"source/default comparison still refuses observed world rounding");
        Check(worldBefore.TryMap(worldAfter,true,out _,true,true),"restoration admits observed 0.2mm world-height round trip");
        worldAfter.Items[2].Curve.m_Bezier.b.x+=0.001f;
        Check(!worldBefore.TryMap(worldAfter,true,out _,true,true),"restoration still refuses millimetre horizontal geometry change");
        worldAfter=Graph(100);worldBefore=Graph();worldBefore.Items[0].Node.m_Position.y=worldAfter.Items[0].Node.m_Position.y=511.9453f;worldAfter.Items[0].Node.m_Position.y+=0.0002f;
        Check(worldBefore.TryMap(worldAfter,true,out _,true,true),"native node-height round trip uses bounded restoration tolerance");
        worldBefore.Items[0].Node.m_Position.y=100000;worldAfter.Items[0].Node.m_Position.y=100000.01f;
        Check(!worldBefore.TryMap(worldAfter,true,out _,true,true),"rounding allowance stays capped at large coordinates");
        worldAfter=Graph(100);worldBefore=Graph();worldAfter.Items[2].Curve.m_Bezier.b.y=float.NaN;
        Check(!worldBefore.TryMap(worldAfter,true,out _,true,true),"rounding cannot admit nonfinite live geometry");
        worldAfter=Graph(100);worldAfter.Items[2].Edge.m_End=Id(102);
        Check(!worldBefore.TryMap(worldAfter,true,out _,true,true),"rounding cannot bypass topology");
        worldBefore=Graph();worldAfter=Graph(100);worldBefore.Items[3].Curve.m_Bezier.b.y=worldAfter.Items[3].Curve.m_Bezier.b.y=511.9453f;
        worldAfter.Items[3].Curve.m_Bezier.b.y+=0.0003f;
        Check(!worldBefore.TryMap(worldAfter,true,out _),"generated lane default capture comparison remains strict");
        Check(worldBefore.TryMap(worldAfter,true,out _,true,true),"generated lane regeneration admits observed 0.3mm derived curve rounding");
        worldAfter.Items[3].Curve.m_Bezier.b.y+=0.0004f;
        Check(!worldBefore.TryMap(worldAfter,true,out _,true,true),"generated lane rounding cannot exceed half-millimetre cap");
        worldAfter=Graph(100);worldBefore=Graph();worldBefore.Items[2].Curve.m_Bezier.b.y=worldAfter.Items[2].Curve.m_Bezier.b.y=511.9453f;worldAfter.Items[2].Curve.m_Bezier.b.y+=0.0003f;
        Check(!worldBefore.TryMap(worldAfter,true,out _,true,true),"source edge retains smaller rounding budget");
        Check(expected.ExplainMismatch(Graph(100),true)=="none","diagnostics preserve successful mapping");
        actual=Graph(100);actual.Items=actual.Items.Take(2).ToArray();Check(expected.ExplainMismatch(actual,true).StartsWith("item count"),"diagnostics identify graph count mismatch");
        actual=Graph(100);actual.Items[2].Curve.m_Length=90;Check(expected.ExplainMismatch(actual,true).StartsWith("typed mapping"),"diagnostics identify typed geometry mismatch");
        actual=Graph(100);actual.Items[0].Connections=Array.Empty<Entity>();Check(expected.ExplainMismatch(actual,true).StartsWith("connections/"),"diagnostics identify connection mismatch");
        Check(new AreaCompanionNetwork{Owner=Id(1)}.TryMap(new AreaCompanionNetwork{Owner=Id(10)},true,out _),"area-only empty graph still supported");
        var anchorPrefab=(Game.Prefabs.PrefabBase)System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(typeof(Game.Prefabs.ObjectPrefab));
        AreaCompanionNetwork Anchored(int offset){var g=Graph(offset);g.Anchors=new[]{new AreaCompanionNetwork.Anchor{Id=Id(offset+20),Owner=g.Owner,Prefab=anchorPrefab,Transform=new Game.Objects.Transform{m_Position=new float3(2,3,4),m_Rotation=quaternion.identity}}};g.Items[3].Lane.m_StartNode=new PathNode(Id(offset+20),(ushort)7);return g;}
        var owned=Anchored(0);var rebuilt=Anchored(100);
        Check(owned.TryMap(owned,true,out _),"owned object anchor closes lane path reference in self capture");
        Check(owned.TryMap(rebuilt,true,out var anchorMap)&&anchorMap[Id(20)]==Id(120),"recreated object anchor remaps lane path owner with typed pose proof");
        rebuilt.Anchors[0].Owner=Id(999);Check(!owned.TryMap(rebuilt,true,out _),"anchor external ownership refused");
        rebuilt=Anchored(100);rebuilt.Items[3].Lane.m_StartNode=new PathNode(Id(999),(ushort)7);Check(!owned.TryMap(rebuilt,true,out _),"unresolved path owner remains refused");
        rebuilt=Anchored(100);rebuilt.Items[3].Lane.m_StartNode=new PathNode(Id(120),(ushort)8);Check(!owned.TryMap(rebuilt,true,out _),"anchor remapping preserves path bits");
        rebuilt=Anchored(100);rebuilt.Anchors[0].Transform.m_Position.x++;Check(!owned.TryMap(rebuilt,true,out _),"anchor pose change refused");
        rebuilt=Anchored(100);rebuilt.Anchors[0].Prefab=null;Check(!owned.TryMap(rebuilt,true,out _),"anchor prefab reference required");
        rebuilt=Anchored(100);rebuilt.Anchors=Array.Empty<AreaCompanionNetwork.Anchor>();Check(!owned.TryMap(rebuilt,true,out _),"missing anchor refused");
        rebuilt=Anchored(0);rebuilt.Anchors[0].Transform.m_Position.x++;Check(!owned.TryMap(rebuilt,true,out _),"surviving anchor identity cannot bypass typed pose change");
        rebuilt=Anchored(100);rebuilt.Anchors[0].Transform.m_Position.x=float.NaN;Check(!rebuilt.TryMap(rebuilt,true,out _),"nonfinite anchor refused");
        rebuilt=Anchored(100);rebuilt.Anchors[0].HasLocal=true;Check(!owned.TryMap(rebuilt,true,out _),"anchor attachment presence retained");
        owned=Anchored(0);rebuilt=Anchored(100);owned.Anchors[0].HasLocal=rebuilt.Anchors[0].HasLocal=true;
        owned.Anchors[0].Local=rebuilt.Anchors[0].Local=new Game.Tools.LocalTransformCache{m_Position=new float3(2,3,4),m_Rotation=quaternion.identity,m_ParentMesh=0,m_Probability=100};
        Check(owned.TryMap(rebuilt,true,out _),"recreated anchor preserves exact local attachment values");
        rebuilt.Anchors[0].Local.m_ParentMesh=1;Check(!owned.TryMap(rebuilt,true,out _),"anchor mesh attachment change refused");
        rebuilt.Anchors[0].Local.m_Position.x=float.NaN;Check(!rebuilt.TryMap(rebuilt,true,out _),"nonfinite anchor local cache refused");
        return checks;
    }
}
